	private static boolean contains(Throwable failure, Throwable expected) {
		if (failure == null) {
			return false;
		}
		if (failure == expected || contains(failure.getCause(), expected)) {
			return true;
		}
		for (Throwable suppressed : failure.getSuppressed()) {
			if (contains(suppressed, expected)) {
				return true;
			}
		}
		return false;
	}

